def transform(grid):
 from collections import Counter
 H=len(grid); W=len(grid[0]); seen=set(); comps=[]
 for r in range(H):
  for c in range(W):
   if grid[r][c] and (r,c) not in seen:
    col=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); s=[]
    while stack:
     a,b=stack.pop(); s.append((a,b))
     for da in (-1,0,1):
      for db in (-1,0,1):
       x,y=a+da,b+db
       if 0<=x<H and 0<=y<W and (x,y) not in seen and grid[x][y]==col:
        seen.add((x,y)); stack.append((x,y))
    comps.append((s,col))
 candidates=[]
 for s,col in comps:
  if all(0<r<H-1 and 0<c<W-1 for r,c in s): candidates.append((s,col))
 if not candidates: candidates=comps
 s,col=max(candidates,key=lambda t:len(t[0]))
 mr=min(r for r,c in s); mc=min(c for r,c in s)
 shape={(r-mr,c-mc) for r,c in s}; ht=max(r for r,c in shape)+1; wt=max(c for r,c in shape)+1
 out=[[0]*W for _ in range(H)]
 for r in range(H-ht): out[r+ht]=grid[r][:]
 for s,color in comps:
  if not any(r==0 for r,c in s): continue
  observed=set(s); matches=[]
  for a in range(-ht+1,1):
   for b in range(-wt+1,W):
    points={(a+x,b+y) for x,y in shape}
    visible={(r,c) for r,c in points if 0<=r<H and 0<=c<W}
    if visible==observed: matches.append(points)
  if matches:
   for r,c in matches[0]:
    if 0<=r+ht<H and 0<=c<W: out[r+ht][c]=color
 return out

